pub fn write_fixture(output: &Path, slide_one: &[u8], slide_two: &[u8]) {
    if let Some(parent) = output.parent() {
        fs::create_dir_all(parent).expect("create fixture directory");
    }
    let options = EntryOptions::deterministic(CompressionMethod::Deflate);
    let entries = [
        ("[Content_Types].xml", CONTENT_TYPES),
        ("_rels/.rels", PACKAGE_RELATIONSHIPS),
        ("ppt/presentation.xml", PRESENTATION),
        (
            "ppt/_rels/presentation.xml.rels",
            PRESENTATION_RELATIONSHIPS,
        ),
        ("ppt/presProps.xml", PRESENTATION_PROPERTIES),
        ("ppt/slideMasters/slideMaster1.xml", SLIDE_MASTER),
        (
            "ppt/slideMasters/_rels/slideMaster1.xml.rels",
            SLIDE_MASTER_RELATIONSHIPS,
        ),
        ("ppt/slideLayouts/slideLayout1.xml", SLIDE_LAYOUT),
        (
            "ppt/slideLayouts/_rels/slideLayout1.xml.rels",
            SLIDE_LAYOUT_RELATIONSHIPS,
        ),
        ("ppt/theme/theme1.xml", THEME),
        ("ppt/slides/slide1.xml", slide_one),
        ("ppt/slides/_rels/slide1.xml.rels", SLIDE_ONE_RELATIONSHIPS),
        ("ppt/slides/slide2.xml", slide_two),
        ("ppt/slides/_rels/slide2.xml.rels", SLIDE_TWO_RELATIONSHIPS),
    ];

    let mut writer = ZipWriter::new(VecSink::new());
    for (name, bytes) in entries {
        writer
            .write_entry(name, bytes, &options)
            .expect("write entry");
    }
    writer
        .write_entry(
            "ppt/media/original.png",
            PLACEHOLDER_PNG,
            &EntryOptions::deterministic(CompressionMethod::Stored),
        )
        .expect("write placeholder image");
    fs::write(output, writer.finish().unwrap().0.into_inner()).expect("write fixture");
}
